INSERT INTO content_releases VALUES('term-b-explorers-v1','published','6c87fe8bd29aa3eabd802a8e9a9b6f74c991b7e13f1fb3e11f105d5b9cde7eec',unixepoch()*1000);
INSERT INTO lessons VALUES('P1B-U02-L1',1,'term-b-explorers-v1',1,'B',2,'水果菜单里的喜欢','{"id":"P1B-U02-L1","unitId":"P1B-U02","grade":1,"term":"B","unitNumber":2,"unitLesson":1,"order":5,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":10,"title":"水果菜单里的喜欢","releaseId":"term-b-explorers-v1","unitTitle":"我喜欢的水果","cards":[{"title":"水果菜单里的喜欢","rule":"说一般喜好可用I like加水果复数。apples表示苹果这一类；不是看到很多水果就一定喜欢。先看角色菜单上的文字。","example":"I like sweet peaches.","translation":"我喜欢甜桃子。"},{"title":"水果菜单里的喜欢","rule":"说一般喜好可用I like加水果复数。apples表示苹果这一类；不是看到很多水果就一定喜欢。先看角色菜单上的文字。","example":"I like yellow melons.","translation":"我喜欢黄甜瓜。"},{"title":"水果菜单里的喜欢","rule":"说一般喜好可用I like加水果复数。apples表示苹果这一类；不是看到很多水果就一定喜欢。先看角色菜单上的文字。","example":"I like fresh cherries.","translation":"我喜欢新鲜樱桃。"}],"vocabulary":[{"word":"peach","meaning":"桃子"},{"word":"melon","meaning":"甜瓜"},{"word":"cherry","meaning":"樱桃"},{"word":"like","meaning":"喜欢"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.preferences","sentence.negative","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P1B-U02-L2',1,'term-b-explorers-v1',1,'B',2,'不喜欢也能礼貌说','{"id":"P1B-U02-L2","unitId":"P1B-U02","grade":1,"term":"B","unitNumber":2,"unitLesson":2,"order":6,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":10,"title":"不喜欢也能礼貌说","releaseId":"term-b-explorers-v1","unitTitle":"我喜欢的水果","cards":[{"title":"不喜欢也能礼貌说","rule":"I don''t like表示我不喜欢，don''t后用like原形；也可写I do not like。角色的口味不代表你的口味，没有必须喜欢的水果。","example":"I don''t like sour plums.","translation":"我不喜欢酸李子。"},{"title":"不喜欢也能礼貌说","rule":"I don''t like表示我不喜欢，don''t后用like原形；也可写I do not like。角色的口味不代表你的口味，没有必须喜欢的水果。","example":"I do not like hard pears.","translation":"我不喜欢硬梨。"},{"title":"不喜欢也能礼貌说","rule":"I don''t like表示我不喜欢，don''t后用like原形；也可写I do not like。角色的口味不代表你的口味，没有必须喜欢的水果。","example":"I like ripe bananas.","translation":"我喜欢熟香蕉。"}],"vocabulary":[{"word":"plum","meaning":"李子"},{"word":"sour","meaning":"酸的"},{"word":"ripe","meaning":"成熟的"},{"word":"don''t","meaning":"不（do not的缩写）"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.preferences","sentence.negative","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P1B-U02-L3',1,'term-b-explorers-v1',1,'B',2,'问问伙伴的口味','{"id":"P1B-U02-L3","unitId":"P1B-U02","grade":1,"term":"B","unitNumber":2,"unitLesson":3,"order":7,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":10,"title":"问问伙伴的口味","releaseId":"term-b-explorers-v1","unitTitle":"我喜欢的水果","cards":[{"title":"问问伙伴的口味","rule":"询问对方的一般喜好用Do you like…?，like保留原形，you表示对方。末尾用问号；问题不能替别人作答。","example":"Do you like sweet mangoes?","translation":"你喜欢甜芒果吗？"},{"title":"问问伙伴的口味","rule":"询问对方的一般喜好用Do you like…?，like保留原形，you表示对方。末尾用问号；问题不能替别人作答。","example":"Do you like soft peaches?","translation":"你喜欢软桃子吗？"},{"title":"问问伙伴的口味","rule":"询问对方的一般喜好用Do you like…?，like保留原形，you表示对方。末尾用问号；问题不能替别人作答。","example":"Do you like these little plums?","translation":"你喜欢这些小李子吗？"}],"vocabulary":[{"word":"mango","meaning":"芒果"},{"word":"sweet","meaning":"甜的"},{"word":"you","meaning":"你"},{"word":"do","meaning":"构成这里的疑问句"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.preferences","sentence.negative","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P1B-U02-L4',1,'term-b-explorers-v1',1,'B',2,'听清回答再配菜单','{"id":"P1B-U02-L4","unitId":"P1B-U02","grade":1,"term":"B","unitNumber":2,"unitLesson":4,"order":8,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":10,"title":"听清回答再配菜单","releaseId":"term-b-explorers-v1","unitTitle":"我喜欢的水果","cards":[{"title":"听清回答再配菜单","rule":"对Do you like…?作简短回答：Yes, I do.或No, I don''t.。yes和no要与角色的完整回答一致，不能只凭水果颜色猜。","example":"Do you like ripe pears? Yes, I do.","translation":"你喜欢熟梨吗？是的，我喜欢。"},{"title":"听清回答再配菜单","rule":"对Do you like…?作简短回答：Yes, I do.或No, I don''t.。yes和no要与角色的完整回答一致，不能只凭水果颜色猜。","example":"Do you like sour peaches? No, I don''t.","translation":"你喜欢酸桃子吗？不，我不喜欢。"},{"title":"听清回答再配菜单","rule":"对Do you like…?作简短回答：Yes, I do.或No, I don''t.。yes和no要与角色的完整回答一致，不能只凭水果颜色猜。","example":"Yes, I do. I like sweet plums.","translation":"是的。我喜欢甜李子。"}],"vocabulary":[{"word":"yes","meaning":"是"},{"word":"no","meaning":"不"},{"word":"fruit","meaning":"水果"},{"word":"menu","meaning":"菜单"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.preferences","sentence.negative","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U02-L1',1,'term-b-explorers-v1',2,'B',2,'把班级指令读明白','{"id":"P2B-U02-L1","unitId":"P2B-U02","grade":2,"term":"B","unitNumber":2,"unitLesson":1,"order":5,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":10,"title":"把班级指令读明白","releaseId":"term-b-explorers-v1","unitTitle":"一起上学","cards":[{"title":"把班级指令读明白","rule":"英语祈使句通常直接以动词原形开头，不加主语you。先读指令再判断要做什么；这里只操作图卡，不要求实际移动。","example":"Open the classroom window, please.","translation":"请打开教室窗户。"},{"title":"把班级指令读明白","rule":"英语祈使句通常直接以动词原形开头，不加主语you。先读指令再判断要做什么；这里只操作图卡，不要求实际移动。","example":"Close your picture book.","translation":"合上你的图画书。"},{"title":"把班级指令读明白","rule":"英语祈使句通常直接以动词原形开头，不加主语you。先读指令再判断要做什么；这里只操作图卡，不要求实际移动。","example":"Put the blue card on the desk.","translation":"把蓝卡片放在书桌上。"}],"vocabulary":[{"word":"open","meaning":"打开"},{"word":"close","meaning":"关上；合上"},{"word":"desk","meaning":"书桌"},{"word":"card","meaning":"卡片"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.requests","sentence.negative","sentence.patterns.suggestions"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U02-L2',1,'term-b-explorers-v1',2,'B',2,'规则里的Don''t','{"id":"P2B-U02-L2","unitId":"P2B-U02","grade":2,"term":"B","unitNumber":2,"unitLesson":2,"order":6,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":10,"title":"规则里的Don''t","releaseId":"term-b-explorers-v1","unitTitle":"一起上学","cards":[{"title":"规则里的Don''t","rule":"禁止做某事可用Don''t加动词原形，也可写Do not。读清not：Don''t run与Run的意思不同。班级规则属于虚构图卡情景。","example":"Don''t draw on the classroom door.","translation":"不要在教室门上画画。"},{"title":"规则里的Don''t","rule":"禁止做某事可用Don''t加动词原形，也可写Do not。读清not：Don''t run与Run的意思不同。班级规则属于虚构图卡情景。","example":"Do not fold the library map.","translation":"不要折图书馆地图。"},{"title":"规则里的Don''t","rule":"禁止做某事可用Don''t加动词原形，也可写Do not。读清not：Don''t run与Run的意思不同。班级规则属于虚构图卡情景。","example":"Don''t push the paper puppets.","translation":"不要推纸偶。"}],"vocabulary":[{"word":"rule","meaning":"规则"},{"word":"push","meaning":"推"},{"word":"fold","meaning":"折叠"},{"word":"draw","meaning":"画"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.requests","sentence.negative","sentence.patterns.suggestions"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U02-L3',1,'term-b-explorers-v1',2,'B',2,'加上Please更有礼貌','{"id":"P2B-U02-L3","unitId":"P2B-U02","grade":2,"term":"B","unitNumber":2,"unitLesson":3,"order":7,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":10,"title":"加上Please更有礼貌","releaseId":"term-b-explorers-v1","unitTitle":"一起上学","cards":[{"title":"加上Please更有礼貌","rule":"please可放在指令开头或末尾，使表达更礼貌；它不把动词变成第三人称。按给定词块排序，不把另一种正确位置误判为语法错误。","example":"Please share the coloured paper.","translation":"请分享彩纸。"},{"title":"加上Please更有礼貌","rule":"please可放在指令开头或末尾，使表达更礼貌；它不把动词变成第三人称。按给定词块排序，不把另一种正确位置误判为语法错误。","example":"Pass me the blue ruler, please.","translation":"请把蓝尺子递给我。"},{"title":"加上Please更有礼貌","rule":"please可放在指令开头或末尾，使表达更礼貌；它不把动词变成第三人称。按给定词块排序，不把另一种正确位置误判为语法错误。","example":"Please wait beside the story table.","translation":"请在故事桌旁等候。"}],"vocabulary":[{"word":"please","meaning":"请"},{"word":"share","meaning":"分享"},{"word":"pass","meaning":"递给"},{"word":"wait","meaning":"等候"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.requests","sentence.negative","sentence.patterns.suggestions"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U02-L4',1,'term-b-explorers-v1',2,'B',2,'Let''s一起做一件事','{"id":"P2B-U02-L4","unitId":"P2B-U02","grade":2,"term":"B","unitNumber":2,"unitLesson":4,"order":8,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":10,"title":"Let''s一起做一件事","releaseId":"term-b-explorers-v1","unitTitle":"一起上学","cards":[{"title":"Let''s一起做一件事","rule":"Let''s是let us的缩写，用Let''s加动词原形提出一起做事的建议。建议可以商量，不是对方必须同意的命令。","example":"Let''s make a class picture book.","translation":"我们一起做班级图画书吧。"},{"title":"Let''s一起做一件事","rule":"Let''s是let us的缩写，用Let''s加动词原形提出一起做事的建议。建议可以商量，不是对方必须同意的命令。","example":"Let''s count the paper stars.","translation":"我们一起数纸星星吧。"},{"title":"Let''s一起做一件事","rule":"Let''s是let us的缩写，用Let''s加动词原形提出一起做事的建议。建议可以商量，不是对方必须同意的命令。","example":"Let''s read the new rule card.","translation":"我们一起读新规则卡吧。"}],"vocabulary":[{"word":"let''s","meaning":"我们一起……吧"},{"word":"together","meaning":"一起"},{"word":"count","meaning":"数数"},{"word":"make","meaning":"制作"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.requests","sentence.negative","sentence.patterns.suggestions"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U02-L1',1,'term-b-explorers-v1',3,'B',2,'Should是在提建议','{"id":"P3B-U02-L1","unitId":"P3B-U02","grade":3,"term":"B","unitNumber":2,"unitLesson":1,"order":5,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"title":"Should是在提建议","releaseId":"term-b-explorers-v1","unitTitle":"健康的小建议","cards":[{"title":"Should是在提建议","rule":"should后接动词原形，表示建议，不等于必须。这是故事角色的语言练习，不判断真实身体状况；实际不舒服要告诉照顾自己的成人。","example":"You should tell your teacher how you feel.","translation":"你应该告诉老师你的感受。"},{"title":"Should是在提建议","rule":"should后接动词原形，表示建议，不等于必须。这是故事角色的语言练习，不判断真实身体状况；实际不舒服要告诉照顾自己的成人。","example":"You should take a quiet break.","translation":"你应该安静地休息一下。"},{"title":"Should是在提建议","rule":"should后接动词原形，表示建议，不等于必须。这是故事角色的语言练习，不判断真实身体状况；实际不舒服要告诉照顾自己的成人。","example":"You should ask an adult for help.","translation":"你应该向成人寻求帮助。"}],"vocabulary":[{"word":"should","meaning":"应该（提出建议）"},{"word":"break","meaning":"休息"},{"word":"tired","meaning":"疲倦的"},{"word":"adult","meaning":"成人"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.patterns.suggestions","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U02-L2',1,'term-b-explorers-v1',3,'B',2,'Shouldn''t把建议变成否定','{"id":"P3B-U02-L2","unitId":"P3B-U02","grade":3,"term":"B","unitNumber":2,"unitLesson":2,"order":6,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"title":"Shouldn''t把建议变成否定","releaseId":"term-b-explorers-v1","unitTitle":"健康的小建议","cards":[{"title":"Shouldn''t把建议变成否定","rule":"shouldn''t是should not的缩写，后面仍用动词原形。先分清肯定与否定；本课只理解图卡给出的建议，不自行判断真实健康问题。","example":"You shouldn''t hide a problem from an adult.","translation":"你不应该向成人隐瞒困难。"},{"title":"Shouldn''t把建议变成否定","rule":"shouldn''t是should not的缩写，后面仍用动词原形。先分清肯定与否定；本课只理解图卡给出的建议，不自行判断真实健康问题。","example":"You should not push a tired story character.","translation":"你不应该推疲倦的故事角色。"},{"title":"Shouldn''t把建议变成否定","rule":"shouldn''t是should not的缩写，后面仍用动词原形。先分清肯定与否定；本课只理解图卡给出的建议，不自行判断真实健康问题。","example":"You should listen to the character''s words.","translation":"你应该听角色说的话。"}],"vocabulary":[{"word":"shouldn''t","meaning":"不应该"},{"word":"hide","meaning":"隐瞒；隐藏"},{"word":"problem","meaning":"困难；问题"},{"word":"listen","meaning":"听"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.patterns.suggestions","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U02-L3',1,'term-b-explorers-v1',3,'B',2,'Should开头问建议','{"id":"P3B-U02-L3","unitId":"P3B-U02","grade":3,"term":"B","unitNumber":2,"unitLesson":3,"order":7,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"title":"Should开头问建议","releaseId":"term-b-explorers-v1","unitTitle":"健康的小建议","cards":[{"title":"Should开头问建议","rule":"询问建议可把Should放在主语前面：Should I…?。主语后动词用原形，句末问号。问题提出一个选择，不表示已经做过。","example":"Should I tell the story teacher?","translation":"我应该告诉故事里的老师吗？"},{"title":"Should开头问建议","rule":"询问建议可把Should放在主语前面：Should I…?。主语后动词用原形，句末问号。问题提出一个选择，不表示已经做过。","example":"Should we choose a quiet game?","translation":"我们应该选一个安静的游戏吗？"},{"title":"Should开头问建议","rule":"询问建议可把Should放在主语前面：Should I…?。主语后动词用原形，句末问号。问题提出一个选择，不表示已经做过。","example":"Should I read Pip''s help card?","translation":"我应该读Pip的求助卡吗？"}],"vocabulary":[{"word":"advice","meaning":"建议"},{"word":"choose","meaning":"选择"},{"word":"quiet","meaning":"安静的"},{"word":"help","meaning":"帮助"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.patterns.suggestions","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U02-L4',1,'term-b-explorers-v1',3,'B',2,'用简答回应建议问句','{"id":"P3B-U02-L4","unitId":"P3B-U02","grade":3,"term":"B","unitNumber":2,"unitLesson":4,"order":8,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"title":"用简答回应建议问句","releaseId":"term-b-explorers-v1","unitTitle":"健康的小建议","cards":[{"title":"用简答回应建议问句","rule":"回答Should I…?时，对方可用Yes, you should.或No, you shouldn''t.。I在提问者口中表示我，回答者用you指对方；依据故事中的明确答复判断。","example":"Should I tell an adult? Yes, you should.","translation":"我应该告诉成人吗？是的，你应该。"},{"title":"用简答回应建议问句","rule":"回答Should I…?时，对方可用Yes, you should.或No, you shouldn''t.。I在提问者口中表示我，回答者用you指对方；依据故事中的明确答复判断。","example":"Should I hide this worry? No, you shouldn''t.","translation":"我应该隐瞒这份担忧吗？不，你不应该。"},{"title":"用简答回应建议问句","rule":"回答Should I…?时，对方可用Yes, you should.或No, you shouldn''t.。I在提问者口中表示我，回答者用you指对方；依据故事中的明确答复判断。","example":"Yes, you should. Ask the story teacher.","translation":"是的，你应该。问问故事里的老师。"}],"vocabulary":[{"word":"answer","meaning":"回答"},{"word":"worry","meaning":"担忧"},{"word":"teacher","meaning":"老师"},{"word":"reply","meaning":"答复"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.patterns.suggestions","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U02-L1',1,'term-b-explorers-v1',4,'B',2,'节日采访用Did提问','{"id":"P4B-U02-L1","unitId":"P4B-U02","grade":4,"term":"B","unitNumber":2,"unitLesson":1,"order":5,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.past-simple"],"title":"节日采访用Did提问","releaseId":"term-b-explorers-v1","unitTitle":"节日与传统","cards":[{"title":"节日采访用Did提问","rule":"询问过去做没做某事用Did加主语加动词原形。Did承担过去的标记，所以后面不再用过去式。节庆安排均为虚构班级故事。","example":"Did you make lanterns last Friday?","translation":"上周五你做灯笼了吗？"},{"title":"节日采访用Did提问","rule":"询问过去做没做某事用Did加主语加动词原形。Did承担过去的标记，所以后面不再用过去式。节庆安排均为虚构班级故事。","example":"Did Bo visit the class fair?","translation":"Bo参观班级游园会了吗？"},{"title":"节日采访用Did提问","rule":"询问过去做没做某事用Did加主语加动词原形。Did承担过去的标记，所以后面不再用过去式。节庆安排均为虚构班级故事。","example":"Did they carry the paper dragon?","translation":"他们抬纸龙了吗？"}],"vocabulary":[{"word":"lantern","meaning":"灯笼"},{"word":"fair","meaning":"游园会"},{"word":"carry","meaning":"搬；抬"},{"word":"last","meaning":"上一个的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","sentence.negative","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U02-L2',1,'term-b-explorers-v1',4,'B',2,'没做的事情用Didn''t','{"id":"P4B-U02-L2","unitId":"P4B-U02","grade":4,"term":"B","unitNumber":2,"unitLesson":2,"order":6,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.past-simple"],"title":"没做的事情用Didn''t","releaseId":"term-b-explorers-v1","unitTitle":"节日与传统","cards":[{"title":"没做的事情用Didn''t","rule":"过去没做某事可用didn''t加动词原形，也可写did not。不要同时把后面的动词写成过去式；这与wasn''t的用法不同。","example":"We didn''t watch the class parade.","translation":"我们没有观看班级巡游。"},{"title":"没做的事情用Didn''t","rule":"过去没做某事可用didn''t加动词原形，也可写did not。不要同时把后面的动词写成过去式；这与wasn''t的用法不同。","example":"Dot did not make the green lantern.","translation":"Dot没有做绿灯笼。"},{"title":"没做的事情用Didn''t","rule":"过去没做某事可用didn''t加动词原形，也可写did not。不要同时把后面的动词写成过去式；这与wasn''t的用法不同。","example":"Bo didn''t bring a paper drum.","translation":"Bo没有带纸鼓。"}],"vocabulary":[{"word":"didn''t","meaning":"过去没有（did not）"},{"word":"parade","meaning":"巡游"},{"word":"drum","meaning":"鼓"},{"word":"ribbon","meaning":"丝带"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","sentence.negative","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U02-L3',1,'term-b-explorers-v1',4,'B',2,'过去问句怎样简短回应','{"id":"P4B-U02-L3","unitId":"P4B-U02","grade":4,"term":"B","unitNumber":2,"unitLesson":3,"order":7,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.past-simple"],"title":"过去问句怎样简短回应","releaseId":"term-b-explorers-v1","unitTitle":"节日与传统","cards":[{"title":"过去问句怎样简短回应","rule":"Did you…?可回答Yes, I did.或No, I didn''t.；Did they…?则用they。简答跟问题的主语和明确的事实一致。","example":"Did you visit the class fair? Yes, I did.","translation":"你参观班级游园会了吗？是的。"},{"title":"过去问句怎样简短回应","rule":"Did you…?可回答Yes, I did.或No, I didn''t.；Did they…?则用they。简答跟问题的主语和明确的事实一致。","example":"Did Dot paint a drum? No, she didn''t.","translation":"Dot画鼓了吗？不，她没有。"},{"title":"过去问句怎样简短回应","rule":"Did you…?可回答Yes, I did.或No, I didn''t.；Did they…?则用they。简答跟问题的主语和明确的事实一致。","example":"Did they dance at the show? Yes, they did.","translation":"他们在表演中跳舞了吗？是的。"}],"vocabulary":[{"word":"reporter","meaning":"记者"},{"word":"interview","meaning":"采访"},{"word":"show","meaning":"表演"},{"word":"dance","meaning":"跳舞"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","sentence.negative","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U02-L4',1,'term-b-explorers-v1',4,'B',2,'Was与Did不要混在一起','{"id":"P4B-U02-L4","unitId":"P4B-U02","grade":4,"term":"B","unitNumber":2,"unitLesson":4,"order":8,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.past-simple"],"title":"Was与Did不要混在一起","releaseId":"term-b-explorers-v1","unitTitle":"节日与传统","cards":[{"title":"Was与Did不要混在一起","rule":"be动词的过去问句用Was/Were加主语；其他一般过去动作问句用Did加主语加原形。先判断是在问地点或状态，还是在问一个动作。","example":"Was the paper lion beside the stage?","translation":"纸狮子当时在舞台旁吗？"},{"title":"Was与Did不要混在一起","rule":"be动词的过去问句用Was/Were加主语；其他一般过去动作问句用Did加主语加原形。先判断是在问地点或状态，还是在问一个动作。","example":"Were the lanterns in the hall?","translation":"灯笼当时在礼堂里吗？"},{"title":"Was与Did不要混在一起","rule":"be动词的过去问句用Was/Were加主语；其他一般过去动作问句用Did加主语加原形。先判断是在问地点或状态，还是在问一个动作。","example":"Did Bo carry the paper lion?","translation":"Bo抬纸狮子了吗？"}],"vocabulary":[{"word":"was","meaning":"am/is的过去式"},{"word":"were","meaning":"are的过去式"},{"word":"stage","meaning":"舞台"},{"word":"hall","meaning":"礼堂"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","sentence.negative","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U02-L1',1,'term-b-explorers-v1',5,'B',2,'在虚构时刻表里找出发时间','{"id":"P5B-U02-L1","unitId":"P5B-U02","grade":5,"term":"B","unitNumber":2,"unitLesson":1,"order":5,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.future"],"title":"在虚构时刻表里找出发时间","releaseId":"term-b-explorers-v1","unitTitle":"旅行计划师","cards":[{"title":"在虚构时刻表里找出发时间","rule":"When will…?询问将来时间，will后主语再接动词原形。先读这张故事时刻表，不用现实交通知识猜答案；所有时间只属于这次虚构行程。","example":"When will the story bus leave?","translation":"故事巴士将什么时候出发？"},{"title":"在虚构时刻表里找出发时间","rule":"When will…?询问将来时间，will后主语再接动词原形。先读这张故事时刻表，不用现实交通知识猜答案；所有时间只属于这次虚构行程。","example":"It will leave at nine fifteen.","translation":"它将在九点十五分出发。"},{"title":"在虚构时刻表里找出发时间","rule":"When will…?询问将来时间，will后主语再接动词原形。先读这张故事时刻表，不用现实交通知识猜答案；所有时间只属于这次虚构行程。","example":"When will we reach Paper Island?","translation":"我们将什么时候到达纸岛？"}],"vocabulary":[{"word":"leave","meaning":"出发；离开"},{"word":"arrive","meaning":"到达"},{"word":"timetable","meaning":"时刻表"},{"word":"when","meaning":"什么时候"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","sentence.wh","reading.integrating"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U02-L2',1,'term-b-explorers-v1',5,'B',2,'How询问交通方式','{"id":"P5B-U02-L2","unitId":"P5B-U02","grade":5,"term":"B","unitNumber":2,"unitLesson":2,"order":6,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.future"],"title":"How询问交通方式","releaseId":"term-b-explorers-v1","unitTitle":"旅行计划师","cards":[{"title":"How询问交通方式","rule":"How will…get to…?可询问将来的交通方式；by bus/train等通常不加冠词，步行通常说on foot。这里仅按虚构行程卡理解表达。","example":"How will Dot get to Paper Port?","translation":"Dot将怎样到纸港？"},{"title":"How询问交通方式","rule":"How will…get to…?可询问将来的交通方式；by bus/train等通常不加冠词，步行通常说on foot。这里仅按虚构行程卡理解表达。","example":"She will go there by tram.","translation":"她将乘电车去那里。"},{"title":"How询问交通方式","rule":"How will…get to…?可询问将来的交通方式；by bus/train等通常不加冠词，步行通常说on foot。这里仅按虚构行程卡理解表达。","example":"We will go to Model Bay on foot.","translation":"我们将步行到模型湾。"}],"vocabulary":[{"word":"tram","meaning":"电车"},{"word":"ferry","meaning":"渡轮"},{"word":"by","meaning":"乘；用（方式）"},{"word":"on foot","meaning":"步行"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","sentence.wh","reading.integrating"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U02-L3',1,'term-b-explorers-v1',5,'B',2,'How long看懂行程时长','{"id":"P5B-U02-L3","unitId":"P5B-U02","grade":5,"term":"B","unitNumber":2,"unitLesson":3,"order":7,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.future"],"title":"How long看懂行程时长","releaseId":"term-b-explorers-v1","unitTitle":"旅行计划师","cards":[{"title":"How long看懂行程时长","rule":"How long will…take?询问要花多长时间。时刻是几点，时长是多少分钟，两者不同。先读卡片给出的时长；不把虚构路线当真实出行信息。","example":"How long will the model bus trip take?","translation":"模型巴士行程将花多长时间？"},{"title":"How long看懂行程时长","rule":"How long will…take?询问要花多长时间。时刻是几点，时长是多少分钟，两者不同。先读卡片给出的时长；不把虚构路线当真实出行信息。","example":"It will take twenty minutes.","translation":"它将花二十分钟。"},{"title":"How long看懂行程时长","rule":"How long will…take?询问要花多长时间。时刻是几点，时长是多少分钟，两者不同。先读卡片给出的时长；不把虚构路线当真实出行信息。","example":"The toy ferry trip will take half an hour.","translation":"玩具渡轮行程将花半小时。"}],"vocabulary":[{"word":"minute","meaning":"分钟"},{"word":"hour","meaning":"小时"},{"word":"take","meaning":"花费（时间）"},{"word":"trip","meaning":"行程"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","sentence.wh","reading.integrating"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U02-L4',1,'term-b-explorers-v1',5,'B',2,'把两张行程卡合起来读','{"id":"P5B-U02-L4","unitId":"P5B-U02","grade":5,"term":"B","unitNumber":2,"unitLesson":4,"order":8,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.future"],"title":"把两张行程卡合起来读","releaseId":"term-b-explorers-v1","unitTitle":"旅行计划师","cards":[{"title":"把两张行程卡合起来读","rule":"制定计划先核对起点、终点、出发与到达时间。before/after表示先后；will后用原形。这里的选择题只比较卡片明确提供的信息，不猜缺失条件。","example":"We will reach Toy Hall before the show.","translation":"我们将在表演前到玩具礼堂。"},{"title":"把两张行程卡合起来读","rule":"制定计划先核对起点、终点、出发与到达时间。before/after表示先后；will后用原形。这里的选择题只比较卡片明确提供的信息，不猜缺失条件。","example":"The story tram will leave after lunch.","translation":"故事电车将在午饭后出发。"},{"title":"把两张行程卡合起来读","rule":"制定计划先核对起点、终点、出发与到达时间。before/after表示先后；will后用原形。这里的选择题只比较卡片明确提供的信息，不猜缺失条件。","example":"Which route will arrive earlier?","translation":"哪条路线将更早到达？"}],"vocabulary":[{"word":"before","meaning":"在……之前"},{"word":"after","meaning":"在……之后"},{"word":"route","meaning":"路线"},{"word":"earlier","meaning":"更早"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","sentence.wh","reading.integrating"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U02-L1',1,'term-b-explorers-v1',6,'B',2,'分清可核对信息与个人看法','{"id":"P6B-U02-L1","unitId":"P6B-U02","grade":6,"term":"B","unitNumber":2,"unitLesson":1,"order":5,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"title":"分清可核对信息与个人看法","releaseId":"term-b-explorers-v1","unitTitle":"媒体小侦探","cards":[{"title":"分清可核对信息与个人看法","rule":"有时间、数量等依据的陈述可以核对；I think…fun表达这里的个人感受。可核对不代表已证实，仍要找证据。本课所有公告均为虚构文本。","example":"The club notice lists six paper boats.","translation":"社团公告列出了六只纸船。"},{"title":"分清可核对信息与个人看法","rule":"有时间、数量等依据的陈述可以核对；I think…fun表达这里的个人感受。可核对不代表已证实，仍要找证据。本课所有公告均为虚构文本。","example":"I think this is a lovely boat.","translation":"我觉得这是一只可爱的船。"},{"title":"分清可核对信息与个人看法","rule":"有时间、数量等依据的陈述可以核对；I think…fun表达这里的个人感受。可核对不代表已证实，仍要找证据。本课所有公告均为虚构文本。","example":"A checkable claim still needs evidence.","translation":"可核对的说法仍然需要证据。"}],"vocabulary":[{"word":"fact","meaning":"事实"},{"word":"opinion","meaning":"观点；看法"},{"word":"evidence","meaning":"证据"},{"word":"notice","meaning":"公告"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["reading.details","reading.inference","sentence.connectives"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U02-L2',1,'term-b-explorers-v1',6,'B',2,'Because把原因说清楚','{"id":"P6B-U02-L2","unitId":"P6B-U02","grade":6,"term":"B","unitNumber":2,"unitLesson":2,"order":6,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"title":"Because把原因说清楚","releaseId":"term-b-explorers-v1","unitTitle":"媒体小侦探","cards":[{"title":"Because把原因说清楚","rule":"because引出原因；so常引出结果。先看两部分的关系。本课要求用because时不要误填so；其他语境也可用since/as表达原因，不把它们说成错误。","example":"Dot checked the timetable because she needed the departure time.","translation":"Dot核对时刻表，因为她需要出发时间。"},{"title":"Because把原因说清楚","rule":"because引出原因；so常引出结果。先看两部分的关系。本课要求用because时不要误填so；其他语境也可用since/as表达原因，不把它们说成错误。","example":"The card was unclear, so Bo asked for another copy.","translation":"卡片不清楚，所以Bo要了另一份。"},{"title":"Because把原因说清楚","rule":"because引出原因；so常引出结果。先看两部分的关系。本课要求用because时不要误填so；其他语境也可用since/as表达原因，不把它们说成错误。","example":"A reason should support the claim beside it.","translation":"原因应该支持旁边的说法。"}],"vocabulary":[{"word":"because","meaning":"因为"},{"word":"reason","meaning":"原因"},{"word":"claim","meaning":"说法；主张"},{"word":"check","meaning":"核对"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["reading.details","reading.inference","sentence.connectives"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U02-L3',1,'term-b-explorers-v1',6,'B',2,'According to先标明出处','{"id":"P6B-U02-L3","unitId":"P6B-U02","grade":6,"term":"B","unitNumber":2,"unitLesson":3,"order":7,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"title":"According to先标明出处","releaseId":"term-b-explorers-v1","unitTitle":"媒体小侦探","cards":[{"title":"According to先标明出处","rule":"according to表示根据信息来源。引用公告说明出处，并不保证公告永远正确；代词it/they要回到上下文找指代，不能只凭离它最近的词。","example":"According to the club card, the meeting starts at two.","translation":"根据社团卡片，会议两点开始。"},{"title":"According to先标明出处","rule":"according to表示根据信息来源。引用公告说明出处，并不保证公告永远正确；代词it/they要回到上下文找指代，不能只凭离它最近的词。","example":"The notice lists three boats. They are paper models.","translation":"公告列了三只船。它们是纸模型。"},{"title":"According to先标明出处","rule":"according to表示根据信息来源。引用公告说明出处，并不保证公告永远正确；代词it/they要回到上下文找指代，不能只凭离它最近的词。","example":"The blue poster is dated. It gives a Saturday time.","translation":"蓝海报标有日期。它给出周六的时间。"}],"vocabulary":[{"word":"according to","meaning":"根据"},{"word":"source","meaning":"来源"},{"word":"refer to","meaning":"指代"},{"word":"dated","meaning":"标有日期的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["reading.details","reading.inference","sentence.connectives"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U02-L4',1,'term-b-explorers-v1',6,'B',2,'两份信息不一致时先核对','{"id":"P6B-U02-L4","unitId":"P6B-U02","grade":6,"term":"B","unitNumber":2,"unitLesson":4,"order":8,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"title":"两份信息不一致时先核对","releaseId":"term-b-explorers-v1","unitTitle":"媒体小侦探","cards":[{"title":"两份信息不一致时先核对","rule":"不同文本可能给出冲突信息；but表示这里的对比，because给原因。只依据给出的版本和更正说明作答，信息不足可说还不能确定，不从海报好看或转发多就判断真假。","example":"One poster says Friday, but the correction says Saturday.","translation":"一张海报写周五，但更正写周六。"},{"title":"两份信息不一致时先核对","rule":"不同文本可能给出冲突信息；but表示这里的对比，because给原因。只依据给出的版本和更正说明作答，信息不足可说还不能确定，不从海报好看或转发多就判断真假。","example":"We checked the correction because the dates did not match.","translation":"我们查了更正，因为日期不一致。"},{"title":"两份信息不一致时先核对","rule":"不同文本可能给出冲突信息；but表示这里的对比，because给原因。只依据给出的版本和更正说明作答，信息不足可说还不能确定，不从海报好看或转发多就判断真假。","example":"We need more evidence before deciding.","translation":"作决定前我们需要更多证据。"}],"vocabulary":[{"word":"correction","meaning":"更正"},{"word":"compare","meaning":"比较"},{"word":"match","meaning":"一致；匹配"},{"word":"uncertain","meaning":"不能确定的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["reading.details","reading.inference","sentence.connectives"],"itemCount":9}');
INSERT INTO items VALUES('P1B-U02-L1.p1.listen',1,'P1B-U02-L1',1,'listening.P1B-U02','listening-choice','listen','{"title":"水果菜单里的喜欢","gradeMin":1,"id":"P1B-U02-L1.p1.listen","type":"listen","category":"vocabulary","context":"主动播放一句英文，听清后确认；听不到时可用文字辅助。","prompt":"角色喜欢菜单上的什么？","audioText":"I like the grapes on Dot''s menu.","choices":["葡萄","桃子","梨"]}','{"answers":["葡萄"],"family":"fact-ef25ef0695044f13","hint":"先听人物、动作、物品或位置。需要时使用文字辅助，辅助会单独记录。","explanation":"I like the grapes on Dot''s menu. 对应答案：葡萄。","solutionSentences":["I like the grapes on Dot''s menu."]}','published');
