INSERT INTO items VALUES('P1B-U02-L1.p2.evidence',1,'P1B-U02-L1',1,'reading.P1B-U02','reading-evidence','evidence','{"title":"水果菜单里的喜欢","gradeMin":1,"id":"P1B-U02-L1.p2.evidence","type":"evidence","category":"reading","context":"读小故事，先选支持答案的原句，再回答问题。","prompt":"Dot画了什么？","passage":[{"id":"s1","text":"Dot draws three peaches on her menu."},{"id":"s2","text":"Her favourite fruit is the peach."},{"id":"s3","text":"The menu belongs to a story character."}],"choices":["three peaches","two apples","four pears"]}','{"answers":["[\"s1\",\"three peaches\"]"],"evidenceSolutions":[{"sentenceId":"s1","answer":"three peaches"}],"family":"fact-8edbf32869ddb65e","hint":"回到原文找人物、地点、物品或因果；所选句子必须支持答案。","explanation":"依据：Dot draws three peaches on her menu. 对应答案：three peaches。","solutionSentences":["Dot draws three peaches on her menu."]}','published');
