INSERT INTO items VALUES('P1B-U02-L1.p3.choice',1,'P1B-U02-L1',1,'grammar.preferences','recognition','choice','{"title":"水果菜单里的喜欢","gradeMin":1,"id":"P1B-U02-L1.p3.choice","type":"choice","category":"grammar","context":"用I like表达角色喜欢这些紫葡萄。","prompt":"I ___ these purple grapes.","choices":["like","likes","am"]}','{"answers":["like"],"family":"fact-ec5c0027ec5d78b0","hint":"说一般喜好可用I like加水果复数。apples表示苹果这一类；不是看到很多水果就一定喜欢。先看角色菜单上的文字。","explanation":"I like these purple grapes. 用I like表达角色喜欢这些紫葡萄。 说一般喜好可用I like加水果复数。apples表示苹果这一类；不是看到很多水果就一定喜欢。先看角色菜单上的文字。","solutionSentences":["I like these purple grapes."]}','published');
