INSERT INTO items VALUES('P1B-U02-L1.p6.repair',1,'P1B-U02-L1',1,'grammar.preferences','sentence-editing','repair','{"title":"水果菜单里的喜欢","gradeMin":1,"id":"P1B-U02-L1.p6.repair","type":"repair","category":"grammar","context":"I后用like，不加s。","prompt":"点选一处需要修改的词块，填写改后的词；只改这一处。","editing":{"parts":[{"id":"p0","text":"I"},{"id":"p1","text":"likes"},{"id":"p2","text":"the"},{"id":"p3","text":"tiny"},{"id":"p4","text":"cherries"},{"id":"p5","text":"on"},{"id":"p6","text":"this"},{"id":"p7","text":"menu"},{"id":"p8","text":"."}]}}','{"answers":["[\"p1\",\"like\"]"],"repairs":[{"partId":"p1","replacements":["like"]}],"family":"fact-3df8017e9725fc5c","hint":"说一般喜好可用I like加水果复数。apples表示苹果这一类；不是看到很多水果就一定喜欢。先看角色菜单上的文字。","explanation":"I like the tiny cherries on this menu. I后用like，不加s。 说一般喜好可用I like加水果复数。apples表示苹果这一类；不是看到很多水果就一定喜欢。先看角色菜单上的文字。","solutionSentences":["I like the tiny cherries on this menu."],"evidenceTargets":[]}','published');
