INSERT INTO items VALUES('P1B-U02-L1.p7.sort',1,'P1B-U02-L1',1,'grammar.preferences','rule-classification','sort','{"title":"水果菜单里的喜欢","gradeMin":1,"id":"P1B-U02-L1.p7.sort","type":"sort","category":"grammar","context":"看清两个篮子的意思，把四张卡片分好；可以改放，不计速度。","prompt":"先点卡片，再点篮子，全部放好后一起检查。","sorting":{"cards":[{"id":"ca714bdc583b1","text":"I like green pears."},{"id":"c5b1aa47112ce","text":"I like red peaches."},{"id":"cbc1229aa388e","text":"a yellow melon"},{"id":"c22d537d406cd","text":"a small cherry"}],"groups":[{"id":"g0","label":"喜欢句里的水果复数"},{"id":"g1","label":"一份水果的单数词组"}]}}','{"answers":["[[\"c22d537d406cd\",\"g1\"],[\"c5b1aa47112ce\",\"g0\"],[\"ca714bdc583b1\",\"g0\"],[\"cbc1229aa388e\",\"g1\"]]"],"placements":{"ca714bdc583b1":"g0","c5b1aa47112ce":"g0","cbc1229aa388e":"g1","c22d537d406cd":"g1"},"family":"workshop-set-f0823944e30c954e","hint":"说一般喜好可用I like加水果复数。apples表示苹果这一类；不是看到很多水果就一定喜欢。先看角色菜单上的文字。","explanation":"I like green pears. → 喜欢句里的水果复数；I like red peaches. → 喜欢句里的水果复数；a yellow melon → 一份水果的单数词组；a small cherry → 一份水果的单数词组","solutionSentences":["I like green pears. → 喜欢句里的水果复数","I like red peaches. → 喜欢句里的水果复数","a yellow melon → 一份水果的单数词组","a small cherry → 一份水果的单数词组"],"evidenceTargets":["workshop-target:grammar.preferences:ca714bdc583b1","workshop-target:grammar.preferences:c5b1aa47112ce","workshop-target:grammar.preferences:cbc1229aa388e","workshop-target:grammar.preferences:c22d537d406cd"]}','published');
