INSERT INTO items VALUES('P1B-U02-L1.p8.input',1,'P1B-U02-L1',1,'grammar.preferences','controlled-production','input','{"title":"水果菜单里的喜欢","gradeMin":1,"id":"P1B-U02-L1.p8.input","type":"input","category":"grammar","context":"把like填入角色对绿色苹果的喜好句。","prompt":"I ___ the green apples on my menu."}','{"answers":["like"],"family":"fact-14dad9ccf3a9396c","hint":"说一般喜好可用I like加水果复数。apples表示苹果这一类；不是看到很多水果就一定喜欢。先看角色菜单上的文字。","explanation":"I like the green apples on my menu. 把like填入角色对绿色苹果的喜好句。 说一般喜好可用I like加水果复数。apples表示苹果这一类；不是看到很多水果就一定喜欢。先看角色菜单上的文字。","solutionSentences":["I like the green apples on my menu."]}','published');
