INSERT INTO items VALUES('P1B-U02-L2.p2.evidence',1,'P1B-U02-L2',1,'reading.P1B-U02','reading-evidence','evidence','{"title":"不喜欢也能礼貌说","gradeMin":1,"id":"P1B-U02-L2.p2.evidence","type":"evidence","category":"reading","context":"读小故事，先选支持答案的原句，再回答问题。","prompt":"Bo写不喜欢什么？","passage":[{"id":"s1","text":"Bo writes ''I don''t like these plums.''"},{"id":"s2","text":"He draws a mango beside the words ''I like this fruit.''"},{"id":"s3","text":"Bo and Dot may like different fruit."}],"choices":["these plums","these peaches","these cherries"]}','{"answers":["[\"s1\",\"these plums\"]"],"evidenceSolutions":[{"sentenceId":"s1","answer":"these plums"}],"family":"fact-4b4d695eead4b180","hint":"回到原文找人物、地点、物品或因果；所选句子必须支持答案。","explanation":"依据：Bo writes ''I don''t like these plums.'' 对应答案：these plums。","solutionSentences":["Bo writes ''I don''t like these plums.''"]}','published');
