INSERT INTO items VALUES('P6B-U02-L4.p5.evidence',1,'P6B-U02-L4',1,'reading.P6B-U02','reading-evidence','evidence','{"title":"两份信息不一致时先核对","gradeMin":6,"id":"P6B-U02-L4.p5.evidence","type":"evidence","category":"reading","context":"读小故事，先选支持答案的原句，再回答问题。","prompt":"第二条消息的时间能仅凭本文确认吗？","passage":[{"id":"s1","text":"Old poster: model club, Room 2. Dated correction: Room 5 replaces Room 2."},{"id":"s2","text":"A second message gives a start time but no date or source."},{"id":"s3","text":"A correction needs to clearly identify what it updates."}],"choices":["not yet; source and date are missing","yes; every message is correct","yes; a short message is always newer"]}','{"answers":["[\"s2\",\"not yet; source and date are missing\"]"],"evidenceSolutions":[{"sentenceId":"s2","answer":"not yet; source and date are missing"}],"family":"fact-820d51ba4e682a6b","hint":"回到原文找人物、地点、物品或因果；所选句子必须支持答案。","explanation":"依据：A second message gives a start time but no date or source. 对应答案：not yet; source and date are missing。","solutionSentences":["A second message gives a start time but no date or source."]}','published');
