INSERT INTO items VALUES('P6B-U02-L4.p7.sort',1,'P6B-U02-L4',1,'reading.source-checking','rule-classification','sort','{"title":"两份信息不一致时先核对","gradeMin":6,"id":"P6B-U02-L4.p7.sort","type":"sort","category":"reading","context":"看清两个篮子的意思，把四张卡片分好；可以改放，不计速度。","prompt":"先点卡片，再点篮子，全部放好后一起检查。","sorting":{"cards":[{"id":"ce2beba1bb9b0","text":"Dated correction: Room 8 replaces Room 3."},{"id":"cffebe2b46475","text":"Club record dated 6 May: 12 paper boats."},{"id":"c881893e8e4d6","text":"An undated message says ''changed'' without naming the event."},{"id":"c25ebc3a6b76c","text":"A cropped screenshot gives a time but no source or date."}],"groups":[{"id":"g0","label":"材料明确给出可核对的信息"},{"id":"g1","label":"材料缺少出处或日期需再查"}]}}','{"answers":["[[\"c25ebc3a6b76c\",\"g1\"],[\"c881893e8e4d6\",\"g1\"],[\"ce2beba1bb9b0\",\"g0\"],[\"cffebe2b46475\",\"g0\"]]"],"placements":{"ce2beba1bb9b0":"g0","cffebe2b46475":"g0","c881893e8e4d6":"g1","c25ebc3a6b76c":"g1"},"family":"workshop-set-438faaead1da210c","hint":"不同文本可能给出冲突信息；but表示这里的对比，because给原因。只依据给出的版本和更正说明作答，信息不足可说还不能确定，不从海报好看或转发多就判断真假。","explanation":"Dated correction: Room 8 replaces Room 3. → 材料明确给出可核对的信息；Club record dated 6 May: 12 paper boats. → 材料明确给出可核对的信息；An undated message says ''changed'' without naming the event. → 材料缺少出处或日期需再查；A cropped screenshot gives a time but no source or date. → 材料缺少出处或日期需再查","solutionSentences":["Dated correction: Room 8 replaces Room 3. → 材料明确给出可核对的信息","Club record dated 6 May: 12 paper boats. → 材料明确给出可核对的信息","An undated message says ''changed'' without naming the event. → 材料缺少出处或日期需再查","A cropped screenshot gives a time but no source or date. → 材料缺少出处或日期需再查"],"evidenceTargets":["workshop-target:reading.source-checking:ce2beba1bb9b0","workshop-target:reading.source-checking:cffebe2b46475","workshop-target:reading.source-checking:c881893e8e4d6","workshop-target:reading.source-checking:c25ebc3a6b76c"]}','published');
